contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, bool newStatus) public payable {
        require(target != address(0));
        // read before value
        bool before = c.approvedToLog(target); if (__ESBMC_reverted()) return;
        bool reverted;
        // attempt to call setApprovedLogger; this contract is not the owner of freshly deployed c
        c.setApprovedLogger(target, newStatus); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // read after value
        bool afterVal = c.approvedToLog(target); if (__ESBMC_reverted()) return;
        // General rule: if the call reverted, mapping observable must be unchanged; otherwise it must equal newStatus.
        assert(reverted ? (before == afterVal) : (afterVal == newStatus));
    }
    receive() external payable { }
}

